// Minimal app.js that loads and uses the renderRows function
const rows = [
    { name: "Alice", score: 95 },
    { name: "Bob", score: 87 },
    { name: "Charlie", score: 92 },
    { name: "Diana", score: 78 },
    { name: "Eve", score: 88 }
];

// Render rows sorted by score descending
const rendered = renderRows(rows);

// Insert the table into the DOM
const container = document.getElementById("table-container");
const table = document.createElement("table");
table.border = "1";
table.cellPadding = "8";

table.innerHTML = rendered;
container.appendChild(table);

// Row interface and table rendering function

export interface Row {
    name: string;
    score: number;
}

/**
 * Renders an array of Row objects as an HTML table fragment.
 * Rows are sorted by score in descending order.
 * 
 * @param rows - Array of Row objects
 * @returns HTML string containing <tr><td>name</td><td>score</td></tr> rows
 */
export function renderRows(rows: Row[]): string {
    // Sort by score descending
    const sorted = [...rows].sort((a, b) => b.score - a.score);

    // Build HTML fragment
    const fragment = sorted.map(row => `
        <tr>
            <td>${row.name}</td>
            <td>${row.score}</td>
        </tr>
    `).join("");

    return fragment;
}

